package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.Bundle;import android.text.InputType;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
/** Four named local visual slots, with bounded wallpaper snapshots. Home shortcuts/order are preserved. */
public final class VisualProfilesActivity extends LeoActivity {
 static Set<String> keys(){HashSet<String> keys=new HashSet<String>(Arrays.asList("theme","accent","large-text","warm","list","unified-phone"));for(String app:StyleSettingsActivity.APPS)keys.add("app-theme-"+app);return keys;}
 static File folder(Context c,int slot){if(slot<0||slot>=4)throw new IllegalArgumentException();return new File(c.getFilesDir(),"visual-profile-"+slot);}
 static void save(Context c,int slot,String name)throws Exception{if(name.trim().isEmpty()||name.length()>40)throw new IOException();File dir=folder(c,slot);if(!dir.exists()&&!dir.mkdir())throw new IOException();JSONObject values=new JSONObject();for(Map.Entry<String,?> e:c.getSharedPreferences("appearance",0).getAll().entrySet())if(keys().contains(e.getKey())&&(e.getValue() instanceof Integer||e.getValue() instanceof Boolean))values.put(e.getKey(),e.getValue());JSONObject data=new JSONObject().put("version",1).put("name",name.trim()).put("settings",values);File wall=Appearance.wallpaper(c);data.put("wallpaper",wall.isFile()?android.util.Base64.encodeToString(BackupEngine.atomicBytes(wall,2097152),android.util.Base64.NO_WRAP):JSONObject.NULL);BackupEngine.write(new File(dir,"profile.json"),data.toString().getBytes("UTF-8"));}
 static JSONObject read(Context c,int slot)throws Exception{JSONObject data=new JSONObject(new String(BackupEngine.atomicBytes(new File(folder(c,slot),"profile.json"),3145728),"UTF-8"));if(data.getInt("version")!=1||data.getString("name").length()>40)throw new IOException();JSONObject p=data.getJSONObject("settings");for(Iterator<String> i=p.keys();i.hasNext();){String key=i.next();Object v=p.get(key);if(!keys().contains(key)||!(v instanceof Integer||v instanceof Boolean))throw new IOException();if((key.equals("theme")||key.startsWith("app-theme-"))&&(!(v instanceof Integer)||(Integer)v<0||(Integer)v>=Appearance.COLORS.length))throw new IOException();if(key.equals("accent")&&(!(v instanceof Integer)||(Integer)v< -1||(Integer)v>=Appearance.ACCENTS.length))throw new IOException();if(!key.equals("theme")&&!key.equals("accent")&&!key.startsWith("app-theme-")&&!(v instanceof Boolean))throw new IOException();}if(!data.isNull("wallpaper")&&android.util.Base64.decode(data.getString("wallpaper"),0).length>2097152)throw new IOException();return data;}
 static void apply(Context c,int slot)throws Exception{JSONObject data=read(c,slot);ThemeCheckpoint.save(c);try{if(data.isNull("wallpaper"))new android.util.AtomicFile(Appearance.wallpaper(c)).delete();else BackupEngine.write(Appearance.wallpaper(c),android.util.Base64.decode(data.getString("wallpaper"),0));SharedPreferences.Editor e=c.getSharedPreferences("appearance",0).edit();for(String k:keys())e.remove(k);JSONObject p=data.getJSONObject("settings");for(Iterator<String> i=p.keys();i.hasNext();){String k=i.next();Object v=p.get(k);if(v instanceof Boolean)e.putBoolean(k,(Boolean)v);else e.putInt(k,(Integer)v);}if(!e.commit())throw new IOException();}catch(Exception fail){ThemeCheckpoint.restore(c);throw fail;}}
 protected void onCreate(Bundle b){super.onCreate(b);home();}
 private void home(){ArrayList<String> labels=new ArrayList<String>();for(int n=0;n<4;n++){String name=L.t("Profil gol");try{name=read(this,n).getString("name");}catch(Exception ignored){}labels.add((n+1)+" · "+name);}list(L.t("Profilurile mele"),labels,0,new Choice(){public void pick(final int slot){options(L.t("Profil vizual"),new String[]{L.t("Salvează aspectul actual"),L.t("Aplică profilul"),L.t("Șterge profilul")},new Choice(){public void pick(int action){if(action==0)name(slot);else if(action==1)confirm(slot,false);else confirm(slot,true);}});}},L.t("Colecții Leo"),new Runnable(){public void run(){startActivity(new Intent(VisualProfilesActivity.this,ThemePacksActivity.class));}});}
 private void name(final int slot){LinearLayout form=fields(L.t("Numele profilului"));final EditText name=field(form,L.t("Maximum 40 de caractere"),"",InputType.TYPE_CLASS_TEXT);left=new Runnable(){public void run(){final String label=name.getText().toString();worker.execute(new Runnable(){public void run(){try{save(VisualProfilesActivity.this,slot,label);ui(new Runnable(){public void run(){home();}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("Profilul nu poate fi salvat"));}});}}});}};back=new Runnable(){public void run(){home();}};footer(L.t("Salvează"),"Editor",L.t("Șterge"));name.requestFocus();}
 private void confirm(final int slot,final boolean delete){options(delete?L.t("Ștergi profilul salvat?"):L.t("Aplici culorile, fontul și fundalul?"),new String[]{L.t("Anulează"),delete?L.t("Șterge"):L.t("Aplică")},new Choice(){public void pick(int yes){if(yes!=1)return;worker.execute(new Runnable(){public void run(){try{if(delete)new android.util.AtomicFile(new File(folder(VisualProfilesActivity.this,slot),"profile.json")).delete();else apply(VisualProfilesActivity.this,slot);ui(new Runnable(){public void run(){home();notice(L.t("Modificările se văd la redeschidere"));}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("Profil indisponibil sau invalid"));}});}}});}});}
}
